  "Email address to receive a copy": "\u092a\u094d\u0930\u0924\u093f\u0932\u093f\u092a\u093f \u092a\u094d\u0930\u093e\u092a\u094d\u0924 \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0908\u092e\u0947\u0932 \u092a\u0924\u093e",
  "Embedding Not Allowed": "\u090f\u092e\u094d\u092c\u0947\u0921\u093f\u0902\u0917 \u0915\u0940 \u0905\u0928\u0941\u092e\u0924\u093f \u0928\u0939\u0940\u0902 \u0939\u0948",
  "Enable it in the survey settings to collect and view responses here.": "\u0907\u0938\u0947 \u0938\u0930\u094d\u0935\u0947 \u0938\u0947\u091f\u093f\u0902\u0917\u094d\u0938 \u092e\u0947\u0902 \u0938\u0915\u094d\u0937\u092e \u0915\u0930\u0947\u0902 \u0924\u093e\u0915\u093f \u0906\u092a \u092f\u0939\u093e\u0902 \u092a\u094d\u0930\u0924\u093f\u0915\u094d\u0930\u093f\u092f\u093e\u090f\u0902 \u090f\u0915\u0924\u094d\u0930\u093f\u0924 \u0915\u0930 \u0938\u0915\u0947\u0902 \u0914\u0930 \u0926\u0947\u0916 \u0938\u0915\u0947\u0902",
  "Enable validation (experimental)": "\u092e\u093e\u0928\u094d\u092f\u0915\u0930\u0923 \u0938\u0915\u094d\u0937\u092e \u0915\u0930\u0947\u0902 (\u092a\u094d\u0930\u093e\u092f\u094b\u0917\u093f\u0915)",
  "Error clearing results:": "\u092a\u0930\u093f\u0923\u093e\u092e \u0938\u093e\u092b \u0915\u0930\u0928\u0947 \u092e\u0947\u0902 \u0924\u094d\u0930\u0941\u091f\u093f",
  "Error deleting result:": "\u092a\u0930\u093f\u0923\u093e\u092e \u0939\u091f\u093e\u0928\u0947 \u092e\u0947\u0902 \u0924\u094d\u0930\u0941\u091f\u093f",
  "Error deleting selected results:": "\u091a\u092f\u0928\u093f\u0924 \u092a\u0930\u093f\u0923\u093e\u092e\u094b\u0902 \u0915\u094b \u0939\u091f\u093e\u0928\u0947 \u092e\u0947\u0902 \u0924\u094d\u0930\u0941\u091f\u093f",
  "Error fetching JSON:": "JSON \u092a\u094d\u0930\u093e\u092a\u094d\u0924 \u0915\u0930\u0928\u0947 \u092e\u0947\u0902 \u0924\u094d\u0930\u0941\u091f\u093f",
  "Error fetching details:": "\u0935\u093f\u0935\u0930\u0923 \u0932\u093e\u0928\u0947 \u092e\u0947\u0902 \u0924\u094d\u0930\u0941\u091f\u093f",
  "Error generating form:": "\u092b\u0949\u0930\u094d\u092e \u0909\u0924\u094d\u092a\u0928\u094d\u0928 \u0915\u0930\u0928\u0947 \u092e\u0947\u0902 \u0924\u094d\u0930\u0941\u091f\u093f",
  "Error loading survey:": "\u0938\u0930\u094d\u0935\u0947 \u0932\u094b\u0921 \u0915\u0930\u0928\u0947 \u092e\u0947\u0902 \u0924\u094d\u0930\u0941\u091f\u093f",
  "Error refining existing form:": "\u092e\u094c\u091c\u0942\u0926\u093e \u092b\u093c\u0949\u0930\u094d\u092e \u0915\u094b \u092a\u0930\u093f\u0937\u094d\u0915\u0943\u0924 \u0915\u0930\u0928\u0947 \u092e\u0947\u0902 \u0924\u094d\u0930\u0941\u091f\u093f",
  "Error refining form:": "\u092b\u093c\u0949\u0930\u094d\u092e \u0915\u094b \u092a\u0930\u093f\u0937\u094d\u0915\u0943\u0924 \u0915\u0930\u0928\u0947 \u092e\u0947\u0902 \u0924\u094d\u0930\u0941\u091f\u093f",
  "Error rendering preview:": "\u092a\u0942\u0930\u094d\u0935\u093e\u0935\u0932\u094b\u0915\u0928 \u0930\u0947\u0902\u0921\u0930 \u0915\u0930\u0924\u0947 \u0938\u092e\u092f \u0924\u094d\u0930\u0941\u091f\u093f",
  "Error saving form:": "\u092b\u0949\u0930\u094d\u092e \u0938\u0939\u0947\u091c\u0928\u0947 \u092e\u0947\u0902 \u0924\u094d\u0930\u0941\u091f\u093f",
  "Error:": "\u0924\u094d\u0930\u0941\u091f\u093f",
  "Error: ${error}": "\u0924\u094d\u0930\u0941\u091f\u093f: ${error}",
  "Example: Add rating scales for each question, Include a comments section at the end, Change the first question to a dropdown": "\u0909\u0926\u093e\u0939\u0930\u0923 \u092a\u094d\u0930\u0924\u094d\u092f\u0947\u0915 \u092a\u094d\u0930\u0936\u094d\u0928 \u0915\u0947 \u0932\u093f\u090f \u0930\u0947\u091f\u093f\u0902\u0917 \u0938\u094d\u0915\u0947\u0932 \u091c\u094b\u0921\u093c\u0947\u0902 \u0905\u0902\u0924 \u092e\u0947\u0902 \u090f\u0915 \u091f\u093f\u092a\u094d\u092a\u0923\u093f\u092f\u093e\u0901 \u0905\u0928\u0941\u092d\u093e\u0917 \u0936\u093e\u092e\u093f\u0932 \u0915\u0930\u0947\u0902 \u092a\u0939\u0932\u0940 \u092a\u094d\u0930\u0936\u094d\u0928 \u0915\u094b \u090f\u0915 \u0921\u094d\u0930\u0949\u092a\u0921\u093e\u0909\u0928 \u092e\u0947\u0902 \u092c\u0926\u0932\u0947\u0902",
  "Example: Create a customer satisfaction survey with questions about product quality, delivery experience, and overall satisfaction. Include rating scales and a comments section.": "\u0909\u0926\u093e\u0939\u0930\u0923 \u090f\u0915 \u0917\u094d\u0930\u093e\u0939\u0915 \u0938\u0902\u0924\u0941\u0937\u094d\u091f\u093f \u0938\u0930\u094d\u0935\u0947 \u092c\u0928\u093e\u090f\u0902 \u091c\u093f\u0938\u092e\u0947\u0902 \u0909\u0924\u094d\u092a\u093e\u0926 \u0915\u0940 \u0917\u0941\u0923\u0935\u0924\u094d\u0924\u093e \u0921\u093f\u0932\u0940\u0935\u0930\u0940 \u0915\u0947 \u0905\u0928\u0941\u092d\u0935 \u0914\u0930 \u0915\u0941\u0932 \u0938\u0902\u0924\u0941\u0937\u094d\u091f\u093f \u0938\u0947 \u0938\u0902\u092c\u0902\u0927\u093f\u0924 \u092a\u094d\u0930\u0936\u094d\u0928 \u0939\u094b\u0902 \u0930\u0947\u091f\u093f\u0902\u0917 \u0938\u094d\u0915\u0947\u0932 \u0914\u0930 \u091f\u093f\u092a\u094d\u092a\u0923\u093f\u092f\u094b\u0902 \u0915\u0947 \u0932\u093f\u090f \u090f\u0915 \u0905\u0928\u0941\u092d\u093e\u0917 \u0936\u093e\u092e\u093f\u0932 \u0915\u0930\u0947\u0902",
