  "Failed to delete selected results. Please check the console for details.": "\u091a\u092f\u0928\u093f\u0924 \u092a\u0930\u093f\u0923\u093e\u092e\u094b\u0902 \u0915\u094b \u0939\u091f\u093e\u0928\u0947 \u092e\u0947\u0902 \u0935\u093f\u092b\u0932 \u0915\u0943\u092a\u092f\u093e \u0935\u093f\u0935\u0930\u0923 \u0915\u0947 \u0932\u093f\u090f \u0915\u0902\u0938\u094b\u0932 \u091c\u093e\u0902\u091a\u0947\u0902",
  "Failed to delete the result. Please check the console for details.": "\u092a\u0930\u093f\u0923\u093e\u092e \u0915\u094b \u0939\u091f\u093e\u0928\u0947 \u092e\u0947\u0902 \u0935\u093f\u092b\u0932 \u0930\u0939\u093e \u0915\u0943\u092a\u092f\u093e \u0935\u093f\u0935\u0930\u0923 \u0915\u0947 \u0932\u093f\u090f \u0915\u0902\u0938\u094b\u0932 \u091c\u093e\u0902\u091a\u0947\u0902",
  "Failed to generate form. Please try again.": "\u092b\u0949\u0930\u094d\u092e \u092c\u0928\u093e\u0928\u0947 \u092e\u0947\u0902 \u0935\u093f\u092b\u0932 \u0915\u0943\u092a\u092f\u093e \u092a\u0941\u0928\u0903 \u092a\u094d\u0930\u092f\u093e\u0938 \u0915\u0930\u0947\u0902",
  "Failed to load JSON data. Please check the console for more information.": "JSON \u0921\u0947\u091f\u093e \u0932\u094b\u0921 \u0915\u0930\u0928\u0947 \u092e\u0947\u0902 \u0935\u093f\u092b\u0932 \u0930\u0939\u093e \u0915\u0943\u092a\u092f\u093e \u0905\u0927\u093f\u0915 \u091c\u093e\u0928\u0915\u093e\u0930\u0940 \u0915\u0947 \u0932\u093f\u090f \u0915\u0902\u0938\u094b\u0932 \u091c\u093e\u0902\u091a\u0947\u0902",
  "Failed to load details. Please check the console for more information.": "\u0935\u093f\u0935\u0930\u0923 \u0932\u094b\u0921 \u0915\u0930\u0928\u0947 \u092e\u0947\u0902 \u0935\u093f\u092b\u0932 \u0915\u0943\u092a\u092f\u093e \u0905\u0927\u093f\u0915 \u091c\u093e\u0928\u0915\u093e\u0930\u0940 \u0915\u0947 \u0932\u093f\u090f \u0915\u0902\u0938\u094b\u0932 \u091c\u093e\u0902\u091a\u0947\u0902",
  "Failed to load survey": "\u0938\u0930\u094d\u0935\u0947 \u0932\u094b\u0921 \u0915\u0930\u0928\u0947 \u092e\u0947\u0902 \u0935\u093f\u092b\u0932",
  "Failed to load survey. Please check the URL and try again.": "\u0938\u0930\u094d\u0935\u0947 \u0932\u094b\u0921 \u0915\u0930\u0928\u0947 \u092e\u0947\u0902 \u0935\u093f\u092b\u0932 \u0930\u0939\u093e \u0915\u0943\u092a\u092f\u093e URL \u091c\u093e\u0902\u091a\u0947\u0902 \u0914\u0930 \u092a\u0941\u0928\u0903 \u092a\u094d\u0930\u092f\u093e\u0938 \u0915\u0930\u0947\u0902",
  "Failed to refine existing form. Please try again.": "\u092e\u094c\u091c\u0942\u0926\u093e \u092b\u0949\u0930\u094d\u092e \u0915\u094b \u092a\u0930\u093f\u0937\u094d\u0915\u0943\u0924 \u0915\u0930\u0928\u0947 \u092e\u0947\u0902 \u0935\u093f\u092b\u0932 \u0915\u0943\u092a\u092f\u093e \u092a\u0941\u0928\u0903 \u092a\u094d\u0930\u092f\u093e\u0938 \u0915\u0930\u0947\u0902",
  "Failed to refine form. Your current version is preserved. Please try again.": "\u092b\u0949\u0930\u094d\u092e \u0915\u094b \u092a\u0930\u093f\u0937\u094d\u0915\u0943\u0924 \u0915\u0930\u0928\u0947 \u092e\u0947\u0902 \u0935\u093f\u092b\u0932 \u0906\u092a\u0915\u093e \u0935\u0930\u094d\u0924\u092e\u093e\u0928 \u0938\u0902\u0938\u094d\u0915\u0930\u0923 \u0938\u0941\u0930\u0915\u094d\u0937\u093f\u0924 \u0939\u0948 \u0915\u0943\u092a\u092f\u093e \u092a\u0941\u0928\u0903 \u092a\u094d\u0930\u092f\u093e\u0938 \u0915\u0930\u0947\u0902",
  "Failed to render preview: ${error}": "\u092a\u0942\u0930\u094d\u0935\u093e\u0935\u0932\u094b\u0915\u0928 \u0930\u0947\u0902\u0921\u0930 \u0915\u0930\u0928\u0947 \u092e\u0947\u0902 \u0935\u093f\u092b\u0932: ${error}",
  "Failed to save form: ${error}": "\u092b\u0949\u0930\u094d\u092e \u0938\u0939\u0947\u091c\u0928\u0947 \u092e\u0947\u0902 \u0935\u093f\u092b\u0932: ${error}",
  "Failed to save survey results. Please try again.": "\u0938\u0930\u094d\u0935\u0947 \u092a\u0930\u093f\u0923\u093e\u092e \u0938\u0939\u0947\u091c\u0928\u0947 \u092e\u0947\u0902 \u0905\u0938\u092b\u0932 \u0930\u0939\u093e \u0915\u0943\u092a\u092f\u093e \u092a\u0941\u0928\u0903 \u092a\u094d\u0930\u092f\u093e\u0938 \u0915\u0930\u0947\u0902",
  "Failed to send mail: ${error}": "\u092e\u0947\u0932 \u092d\u0947\u091c\u0928\u0947 \u092e\u0947\u0902 \u0935\u093f\u092b\u0932 \u0930\u0939\u093e: ${error}",
  "Fillable PDF Form": "\u092d\u0930\u0928\u0947 \u092f\u094b\u0917\u094d\u092f \u092a\u0940\u0921\u0940\u090f\u092b \u092b\u0949\u0930\u094d\u092e",
  "Fillable PDF Forms": "\u092d\u0930\u0928\u0947 \u092f\u094b\u0917\u094d\u092f PDF \u092b\u0949\u0930\u094d\u092e\u094d\u0938",
  "First": "\u092a\u0939\u0932\u093e",
  "First Page": "\u092a\u0939\u0932\u093e \u092a\u0943\u0937\u094d\u0920",
