  "Form JSON": "\u092b\u0949\u0930\u094d\u092e JSON",
  "Form Preview": "\u092b\u0949\u0930\u094d\u092e \u092a\u0942\u0930\u094d\u0935\u093e\u0935\u0932\u094b\u0915\u0928",
  "Form Results": "\u092b\u0949\u0930\u094d\u092e \u092a\u0930\u093f\u0923\u093e\u092e",
