  "No file uploaded": "\u0915\u094b\u0908 \u092b\u093c\u093e\u0907\u0932 \u0905\u092a\u0932\u094b\u0921 \u0928\u0939\u0940\u0902 \u0939\u0941\u0908",
  "No form definition available to include in POST": "POST \u092e\u0947\u0902 \u0936\u093e\u092e\u093f\u0932 \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0915\u094b\u0908 \u092b\u0949\u0930\u094d\u092e \u092a\u0930\u093f\u092d\u093e\u0937\u093e \u0909\u092a\u0932\u092c\u094d\u0927 \u0928\u0939\u0940\u0902",
  "No form to preview": "\u092a\u0942\u0930\u094d\u0935\u093e\u0935\u0932\u094b\u0915\u0928 \u0915\u0947 \u0932\u093f\u090f \u0915\u094b\u0908 \u092a\u094d\u0930\u092a\u0924\u094d\u0930 \u0928\u0939\u0940\u0902",
