  "No form versions have been created yet. Use the Form Creator to design your first survey, or upload an existing JSON file using the form above.": "\u0905\u092d\u0940 \u0924\u0915 \u0915\u094b\u0908 \u092b\u0949\u0930\u094d\u092e \u0938\u0902\u0938\u094d\u0915\u0930\u0923 \u0928\u0939\u0940\u0902 \u092c\u0928\u093e\u090f \u0917\u090f \u0939\u0948\u0902 \u092b\u0949\u0930\u094d\u092e \u0915\u094d\u0930\u093f\u090f\u091f\u0930 \u0915\u093e \u0909\u092a\u092f\u094b\u0917 \u0915\u0930\u0915\u0947 \u0905\u092a\u0928\u093e \u092a\u0939\u0932\u093e \u0938\u0930\u094d\u0935\u0947\u0915\u094d\u0937\u0923 \u0921\u093f\u091c\u093c\u093e\u0907\u0928 \u0915\u0930\u0947\u0902 \u092f\u093e \u090a\u092a\u0930 \u0926\u093f\u090f \u0917\u090f \u092b\u0949\u0930\u094d\u092e \u0915\u093e \u0909\u092a\u092f\u094b\u0917 \u0915\u0930\u0915\u0947 \u0915\u093f\u0938\u0940 \u092e\u094c\u091c\u0942\u0926\u093e JSON \u092b\u093c\u093e\u0907\u0932 \u0915\u094b \u0905\u092a\u0932\u094b\u0921 \u0915\u0930\u0947\u0902",
  "No results found matching your search query.": "\u0906\u092a\u0915\u0940 \u0916\u094b\u091c \u0915\u094d\u0935\u0947\u0930\u0940 \u0938\u0947 \u092e\u0947\u0932 \u0916\u093e\u0924\u0947 \u0915\u094b\u0908 \u092a\u0930\u093f\u0923\u093e\u092e \u0928\u0939\u0940\u0902 \u092e\u093f\u0932\u0947",
  "No stored results yet. Once responses are saved, analytics will appear here.": "\u0905\u092d\u0940 \u0915\u094b\u0908 \u0938\u0902\u0917\u094d\u0930\u0939\u0940\u0924 \u092a\u0930\u093f\u0923\u093e\u092e \u0928\u0939\u0940\u0902 \u0939\u0948\u0902 \u090f\u0915 \u092c\u093e\u0930 \u092a\u094d\u0930\u0924\u093f\u0915\u094d\u0930\u093f\u092f\u093e\u090f\u0901 \u0938\u0939\u0947\u091c \u0932\u0940 \u091c\u093e\u090f\u0901\u0917\u0940 \u0924\u094b \u092f\u0939\u093e\u0901 \u0935\u093f\u0936\u094d\u0932\u0947\u0937\u0923 \u0926\u093f\u0916\u093e\u0908 \u0926\u0947\u0902\u0917\u0947",
  "No surveys found below this location.": "\u0907\u0938 \u0938\u094d\u0925\u093e\u0928 \u0915\u0947 \u0928\u0940\u091a\u0947 \u0915\u094b\u0908 \u0938\u0930\u094d\u0935\u0947\u0915\u094d\u0937\u0923 \u0928\u0939\u0940\u0902 \u092e\u093f\u0932\u093e",
  "No version ID provided": "\u0915\u094b\u0908 \u0938\u0902\u0938\u094d\u0915\u0930\u0923 \u0906\u0908\u0921\u0940 \u092a\u094d\u0930\u0926\u093e\u0928 \u0928\u0939\u0940\u0902 \u0915\u0940 \u0917\u0908",
  "Not saved": "\u0938\u0939\u0947\u091c\u093e \u0928\u0939\u0940\u0902 \u0917\u092f\u093e",
  "Open the link in this browser to continue.": "\u091c\u093e\u0930\u0940 \u0930\u0916\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0907\u0938 \u092c\u094d\u0930\u093e\u0909\u091c\u093c\u0930 \u092e\u0947\u0902 \u0932\u093f\u0902\u0915 \u0916\u094b\u0932\u0947\u0902",
  "Optional BCC recipients for result exports (one address per line).": "\u092a\u0930\u093f\u0923\u093e\u092e \u0928\u093f\u0930\u094d\u092f\u093e\u0924\u094b\u0902 \u0915\u0947 \u0932\u093f\u090f \u0935\u0948\u0915\u0932\u094d\u092a\u093f\u0915 \u092c\u0940\u0938\u0940\u0938\u0940 \u092a\u094d\u0930\u093e\u092a\u094d\u0924\u0915\u0930\u094d\u0924\u093e (\u092a\u094d\u0930\u0924\u094d\u092f\u0947\u0915 \u092a\u0902\u0915\u094d\u0924\u093f \u092e\u0947\u0902 \u090f\u0915 \u092a\u0924\u093e)",
  "Optional CC recipients for result exports (one address per line).": "\u092a\u0930\u093f\u0923\u093e\u092e \u0928\u093f\u0930\u094d\u092f\u093e\u0924 \u0915\u0947 \u0932\u093f\u090f \u0935\u0948\u0915\u0932\u094d\u092a\u093f\u0915 CC \u092a\u094d\u0930\u093e\u092a\u094d\u0924\u0915\u0930\u094d\u0924\u093e (\u092a\u094d\u0930\u0924\u093f \u092a\u0902\u0915\u094d\u0924\u093f \u090f\u0915 \u092a\u0924\u093e)",
  "Optional HTTP endpoint to receive submissions as JSON when the POST action is enabled.": "\u0935\u0948\u0915\u0932\u094d\u092a\u093f\u0915 HTTP \u090f\u0902\u0921\u092a\u0949\u0907\u0902\u091f \u091c\u094b POST \u0915\u094d\u0930\u093f\u092f\u093e \u0938\u0915\u094d\u0937\u092e \u0939\u094b\u0928\u0947 \u092a\u0930 \u0938\u092c\u092e\u093f\u0936\u0928 \u0915\u094b JSON \u0915\u0947 \u0930\u0942\u092a \u092e\u0947\u0902 \u092a\u094d\u0930\u093e\u092a\u094d\u0924 \u0915\u0930\u0924\u093e \u0939\u0948",
  "Optional instructions to guide the conversion.": "\u0930\u0942\u092a\u093e\u0902\u0924\u0930\u0923 \u0915\u094b \u0928\u093f\u0930\u094d\u0926\u0947\u0936\u093f\u0924 \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093f\u090f \u0935\u0948\u0915\u0932\u094d\u092a\u093f\u0915 \u0928\u093f\u0930\u094d\u0926\u0947\u0936",
  "Overview of surveys in this section and their submission status.": "\u0907\u0938 \u0916\u0902\u0921 \u092e\u0947\u0902 \u0938\u0930\u094d\u0935\u0947\u0915\u094d\u0937\u0923\u094b\u0902 \u0915\u093e \u0905\u0935\u0932\u094b\u0915\u0928 \u0914\u0930 \u0909\u0928\u0915\u0940 \u092a\u094d\u0930\u0938\u094d\u0924\u0941\u0924\u093f \u0915\u0940 \u0938\u094d\u0925\u093f\u0924\u093f",
